TYPE.TEST:




SetFunctionName("Matrix44Affine(Quaternion &q, Vector3&)");

Quaternion q;
Matrix44Affine ref;
Vector3 v3(2.f, 3.f, 4.f);

q.Set(0, 0, SQRT_HALF, SQRT_HALF);

ref.Set(
     0, 1, 0,
    -1, 0, 0,
     0, 0, 1,
     2, 3, 4
    );

Matrix44Affine r(q, v3);

Validate(IsSimilar(r, ref));




#ifdef HOST_TESTING

        SetFunctionName("Matrix44Affine(const fpu::Matrix44AffineTemplate<FloatClassRHS> &_m)");

        ::rw::math::fpu::Matrix44AffineTemplate<double> doubleUnalignedMatrix;
        ::rw::math::fpu::Matrix44AffineTemplate<float> floatUnalignedMatrix;
        ::rw::math::fpu::Matrix44AffineTemplate<double> doubleAlignedMatrix;
        ::rw::math::fpu::Matrix44AffineTemplate<float> floatAlignedMatrix;

        doubleUnalignedMatrix.Set(
                                  0, 1, 0,
                                 -1, 0, 0,
                                  0, 0, 1,
                                  2, 3, 4
                                 );
        floatUnalignedMatrix.Set(
                                  0, 1, 0,
                                 -1, 0, 0,
                                  0, 0, 1,
                                  2, 3, 4
                                 );
        doubleAlignedMatrix.Set(
                                  0, 1, 0,
                                 -1, 0, 0,
                                  0, 0, 1,
                                  2, 3, 4
                                 );
        floatAlignedMatrix.Set(
                                  0, 1, 0,
                                 -1, 0, 0,
                                  0, 0, 1,
                                  2, 3, 4
                                 );

        Matrix44Affine ref;
        ref.Set(
                                  0, 1, 0,
                                 -1, 0, 0,
                                  0, 0, 1,
                                  2, 3, 4

                );

        Matrix44Affine test_doubleUnalignedMatrix(doubleUnalignedMatrix);
        Matrix44Affine test_floatUnalignedMatrix(doubleUnalignedMatrix);
        Matrix44Affine test_doubleAlignedMatrix(doubleUnalignedMatrix);
        Matrix44Affine test_floatAlignedMatrix(doubleUnalignedMatrix);

        Validate(IsSimilar(test_doubleUnalignedMatrix, ref) &&
                 IsSimilar(test_floatUnalignedMatrix, ref) &&
                 IsSimilar(test_doubleAlignedMatrix, ref) &&
                 IsSimilar(test_floatAlignedMatrix, ref));

#endif

