SetFunctionName("Mult(const Vector4 &v, const Matrix44Affine &m)");

Matrix44Affine m;
Vector4 v4, ra;
v4.Set(6.0f, -1.0f, -3.0f, 1.0f);
m.Set(2.0f, 3.0f, 4.0f, 5.0f, 6.0f, 7.0f, 8.0f, 9.0f, 10.0f, 11.0f, 12.0f, 13.0f);
Vector4 r = Mult(v4, m); // test with non-aliasing

ra.Set(6.0f, -1.0f, -3.0f, 1.0f);
ra = Mult(ra, m);  // test with aliasing

Vector4 ref(
          m.GetElem(0, 0) * v4.X() + m.GetElem(1, 0) * v4.Y() + m.GetElem(2, 0) * v4.Z() + m.GetElem(3, 0) * v4.W(),
          m.GetElem(0, 1) * v4.X() + m.GetElem(1, 1) * v4.Y() + m.GetElem(2, 1) * v4.Z() + m.GetElem(3, 1) * v4.W(),
          m.GetElem(0, 2) * v4.X() + m.GetElem(1, 2) * v4.Y() + m.GetElem(2, 2) * v4.Z() + m.GetElem(3, 2) * v4.W(),
          v4.W());

Validate(IsSimilar(r, ref) && IsSimilar(ra, ref));





SetFunctionName("Mult(const Matrix44Affine &a, const Matrix44Affine &b)");

Matrix44Affine a, b, r, ra, ref;

a.Set(2.0f, 3.0f, 4.0f, 5.0f, 6.0f, 7.0f, 8.0f, 9.0f, 10.0f, 11.0f, 12.0f, 13.0f);
b.Set(4.0f, 3.0f, 4.0f, 1.0f, 6.0f, 7.0f, 8.0f, 1.0f, 10.0f, 11.0f, 12.0f, 1.0f);
ra.Set(2.0f, 3.0f, 4.0f, 5.0f, 6.0f, 7.0f, 8.0f, 9.0f, 10.0f, 11.0f, 12.0f, 13.0f);


r = Mult(a, b); // test with non-aliasing

ra = Mult(ra, b);  // test with aliasing

for (int32_t i = 0; i < 4; ++i)
{
    float_test_type elemI3 = (i==3) ? (float_test_type)1.0f : (float_test_type)0.0f;
    ref.SetElem(i, 0, a.GetElem(i, 0) * b.GetElem(0, 0) + a.GetElem(i, 1) * b.GetElem(1, 0) + a.GetElem(i, 2) * b.GetElem(2, 0) + elemI3 /*a.GetElem(i, 3)*/ * b.GetElem(3, 0) );
    ref.SetElem(i, 1, a.GetElem(i, 0) * b.GetElem(0, 1) + a.GetElem(i, 1) * b.GetElem(1, 1) + a.GetElem(i, 2) * b.GetElem(2, 1) + elemI3 /*a.GetElem(i, 3)*/ * b.GetElem(3, 1) );
    ref.SetElem(i, 2, a.GetElem(i, 0) * b.GetElem(0, 2) + a.GetElem(i, 1) * b.GetElem(1, 2) + a.GetElem(i, 2) * b.GetElem(2, 2) + elemI3 /*a.GetElem(i, 3)*/ * b.GetElem(3, 2) );
}

Validate(IsSimilar(r, ref) && IsSimilar(ra, ref));





SetFunctionName("Transpose(const Matrix44Affine &m)");

Matrix44Affine m, r, ref;

m.Set(
    1,  2,  3,
    5,  6,  7,
    9, 10, 11,
    0,  0,  0
     );
ref.Set(
    1,  5,  9,
    2,  6, 10,
    3,  7, 11,
    0,  0,  0
    );

r = Transpose(m);

Validate(IsSimilar(r, ref));





SetFunctionName("OrthoNormalize(Matrix44Affine &m)");
Matrix44Affine mat1(
        0.98854077f, 0.30964674f, 0.61170041f,
        0.73956566f, 0.25522057f, 0.67839563f,
        0.00371731f, 0.62518794f, 0.33200953f,
        0.59005729f, 0.11574174f, 0.02587099f
    );

Matrix44Affine r1 = OrthoNormalize(mat1);

