SetFunctionName("Stress Test - Inverse(const Matrix44Affine &m)");

Matrix44Affine identity(
    1, 0, 0,
    0, 1, 0,
    0, 0, 1,
    0, 0, 0
    );

bool success = true;
for( int i=0; i < testing::RW_MATH_UNITTEST_TEST_MATRIX_ARRAY_SIZE; i++ )
{
    // Build a matrix from random SQT data
    Matrix44Affine m = Matrix44AffineFromScaleQuaternionTranslation( v3_array[i], q_array[i], v3_array[testing::RW_MATH_UNITTEST_TEST_MATRIX_ARRAY_SIZE - (i+1)] );
    Matrix44Affine inverseM = Inverse(m);
    Matrix44Affine product = Mult( m, inverseM );
    success &= IsSimilar( product, identity, (float_test_type)0.001f );
}

Validate(success);





