SetFunctionName("IsSimilar(const Matrix44Affine &a, const Matrix44Affine &b, float_t epsilon = rw::math::kSmallFloat)");

Matrix44Affine a, b, c, d, e, f;

a.Set(
     1.0f,  2.0f,  0.0f,
    -1.0f,  1.0f,  1.0f,
     1.0f,  2.0f,  3.0f,
     3.0f,  4.0f,  5.0f
    );

b.Set(
    1.0f,  2.0f,  0.0f,
   -1.0f,  1.0f,  1.0f,
    1.0f,  2.0f,  3.0f,
    3.0f,  4.0f,  5.0f
    );
c.Set(
    2.0f,  2.0f,  0.0f,
   -1.0f,  1.0f,  1.0f,
    1.0f,  2.0f,  3.0f,
    3.0f,  4.0f,  5.0f
    );
d.Set(
    1.0f,  2.0f,  0.0f,
   -1.0f,  2.0f,  1.0f,
    1.0f,  2.0f,  3.0f,
    3.0f,  4.0f,  5.0f
    );
e.Set(
    1.0f,  2.0f,  0.0f,
   -1.0f,  1.0f,  1.0f,
    1.0f,  2.0f,  4.0f,
    3.0f,  4.0f,  5.0f
    );
f.Set(
    2.0f,  2.0f,  0.0f,
   -1.0f,  1.0f,  1.0f,
    1.0f,  2.0f,  3.0f,
    3.0f,  4.0f,  6.0f
    );
bool isSimilarTest1 = IsSimilar(a, b);
bool isSimilarTest2 = !IsSimilar(a, c);
bool isSimilarTest3 = !IsSimilar(a, d);
bool isSimilarTest4 = !IsSimilar(a, e);
bool isSimilarTest5 = !IsSimilar(a, f);

bool isSimilarTest6 = true;
for(int row=0;row<4;row++)
{
    for(int col=0;col<3;col++)
    {
        Matrix44Affine testMatrix = a;
        // Perturb the matrix to make it different from a.
        testMatrix.GetElem(row, col) = testMatrix.GetElem(row, col) + (float_test_type)1.0f;
        if( IsSimilar(a,testMatrix) )
        {
            isSimilarTest6 = false;
            break;
        }
    }
}

Validate( isSimilarTest1 &&  isSimilarTest2 &&  isSimilarTest3 &&  isSimilarTest4 && isSimilarTest5 && isSimilarTest6 );




#if !defined EA_PLATFORM_PS3_SPU
        SetFunctionName("IsAnyNaN(Matrix44Affine v)");

        float_test_type nan = float_test_type((float_basic_type)testing::GetNaN());
        int numPermutations = 1 << Matrix44Affine::NumberOfCols;
        bool result = true;
        // Doing all possible permutations of the matrix could be pretty slow. Instead,
        // all permutations along the diagonal will be done.
        for( int curPermutation=0;curPermutation<numPermutations;curPermutation++)
        {
            Matrix44Affine mat;
            mat.SetZero();
            for( int elem = 0; elem < Matrix44Affine::NumberOfCols; elem++ )
            {
                if( curPermutation & (1<<elem) )
                {
                    mat.SetElem( elem, elem, nan );
                }
            }
            if( curPermutation == 0 )
            {
                // All bits are zero so the matrix has no NaN's
                result &= !IsAnyNaN(mat);
            }
            else
            {
                // At least one element is NaN.
                result &= IsAnyNaN(mat);
            }
        }
        Validate(result);
#endif




