SetFunctionName("Matrix44AffineFromQuaternion(const Quaternion &q)");

Quaternion q;
Matrix44Affine r, ref;
float_test_type angle = -PI + 0.0001f;
float_test_type half = 0.5f;
float_test_type zero = 0.0f;

for(; angle < float_test_type(PI); angle += float_test_type(0.25f))
{

    q.Set(Sin(half * angle), zero, zero, Cos(half * angle));

    ref.Set(
        1, 0, 0,
        0, Cos(angle), Sin(angle),
        0, Sin(-angle), Cos(angle),
        0, 0, 0
        );

    r = Matrix44AffineFromQuaternion(q);

    Validate(IsSimilar(r, ref));
}





