        SetFunctionName("Matrix44AffineFromOrthoLH(w, h, zn, zf)");

        bool success = true;
        float_test_type w = 10.0f;
        float_test_type h = 16.0f;
        float_test_type zn = 10.0f;
        float_test_type zf = 80.0f;

#if defined HOST_TESTING
        Matrix44Affine mat(Matrix44AffineFromOrthoLH(w, h, zn, zf));
#else
        Matrix44Affine mat(Matrix44AffineFromOrthoLH<FloatType>(w, h, zn, zf));
#endif

        Vector4 minVec(-w/2.0f, -h/2.0f, zn, (float_test_type)1.0f);
        Vector4 maxVec(w/2.0f, h/2.0f, zf, (float_test_type)1.0f);
        for(int i=0;i<8;i++)
        {
            bool xBool = (i&1)!=0;
            bool yBool = (i&2)!=0;
            bool zBool = (i&4)!=0;
            Vector4 testVector( Select(Mask4(xBool, yBool, zBool, true), maxVec, minVec ) );
            Vector4 result = testVector * mat;

            success &= IsSimilar((float)result.X(), xBool ? 1.0f : -1.0f );
            success &= IsSimilar((float)result.Y(), yBool ? 1.0f : -1.0f );
            success &= IsSimilar((float)result.Z(), zBool ? 1.0f: 0.0f );
        }

        Validate(success);



